with lines as (select id, host, level, k, value from app_logs lateral view outer explode(context) e as k, value) select level, sort_array(collect_set(k)) as k_list, count(case when host = 'h1' then 1 end) as h1_count, size(collect_set(k)) as num_ks, count(case when level = 'INFO' then 1 end) as info_count, count(*) filter (where k = 'trace') as trace_rows from lines group by level order by trace_rows desc nulls last;
